// Описание умения с учётом класса: «Класс:Умение» → «Умение» → без уточнения в скобках
function featureDesc(cls, n) {
  const base = String(n).replace(/^Умение подкласса.*/, 'Умение подкласса');
  return FEATURE_DESC[`${cls}:${base}`] || FEATURE_DESC[base] || FEATURE_DESC[base.replace(/\s*\(.*\)$/, '')] || '';
}

